#include "stv/source_assets.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace stv;
namespace fs=std::filesystem;
static std::vector<u8> read(const fs::path& p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("Cannot open "+p.string());auto n=f.tellg();if(n<0||n>128*1024*1024)throw std::runtime_error("Bad input size");std::vector<u8>b(static_cast<usize>(n));f.seekg(0);f.read(reinterpret_cast<char*>(b.data()),static_cast<std::streamsize>(b.size()));if(!f)throw std::runtime_error("Read failed");return b;}
static void require(Status s,const std::string& name){if(!s)throw std::runtime_error(name+": "+s.message+" at "+std::to_string(s.offset));}
static std::string digest(Bytes b){char s[65];hex(sha256(b).bytes,32,s);return s;}
static void ppm(const fs::path& p,const std::vector<u32>& pixels,unsigned w,unsigned h){std::ofstream f(p,std::ios::binary);f<<"P6\n"<<w<<" "<<h<<"\n255\n";for(auto x:pixels){char rgb[3]={char(x>>16),char(x>>8),char(x)};f.write(rgb,3);}if(!f)throw std::runtime_error("Capture failed");}
int main(int argc,char** argv){try{if(argc!=3)throw std::runtime_error("Usage: stv_sourcecheck source.stva output_directory");auto bytes=read(argv[1]);auto pack=std::make_unique<SourcePack>();require(pack->open({bytes.data(),bytes.size()}),"source pack");fs::path output=argv[2];fs::create_directories(output);std::ofstream report(output/"images.tsv");report<<"file\timage_index\timage\twidth\theight\tanchor_x\tanchor_y\tselector\tpixel_sha256\tpalette_sha256\n";unsigned images=0,bgcount=0,modulecount=0;auto bg=std::make_unique<EditorBackground>();for(unsigned f=0;f<pack->count;++f){auto& entry=pack->entries[f];std::string name=entry.name;if(name.ends_with(".IMG")){EditorImages a;require(a.open(entry.bytes),name);for(unsigned i=0;i<a.count;++i){EditorImage e;EditorPalette p;require(a.image(i,e),name);require(a.palette((e.selector&255)-3,p),name);std::vector<u8> visible;visible.reserve(usize(e.width)*e.height);for(unsigned y=0;y<e.height;++y)visible.insert(visible.end(),e.pixels.data+usize(y)*e.stride,e.pixels.data+usize(y)*e.stride+e.width);report<<name<<'\t'<<i<<'\t'<<e.name<<'\t'<<e.width<<'\t'<<e.height<<'\t'<<e.anchor_x<<'\t'<<e.anchor_y<<'\t'<<e.selector<<'\t'<<digest({visible.data(),visible.size()})<<'\t'<<digest(p.words)<<'\n';++images;}
 // First images in each file: native decoder/raster, not a generated illustration.
 std::vector<u32> atlas(640*480,0x151515);unsigned slots=a.count<80?a.count:80;for(unsigned i=0;i<slots;++i){EditorImage e;require(a.image(i,e),name);if(e.width<=80&&e.height<=60)require(draw_editor_image(a,i,{atlas.data(),640,480,640,atlas.size()},i32((i%8)*80),i32((i/8)*48)),name);}ppm(output/(name+".ppm"),atlas,640,480);
 }else if(name.ends_with(".BDD")){auto stem=name.substr(0,name.size()-4);auto bdb=pack->find((stem+".BDB").c_str());if(!bdb)throw std::runtime_error("Missing BDB");require(bg->open(entry.bytes,bdb->bytes),name);++bgcount;if(bg->invalid_palette_placements)std::cout<<"SOURCE WARNING: "<<name<<": "<<bg->invalid_palette_placements<<" placements reference undefined palette colors (affected modules fail closed).\n";for(unsigned m=0;m<bg->module_count;++m){auto& mod=bg->modules[m];unsigned w=unsigned(mod.right-mod.left+1),h=unsigned(mod.bottom-mod.top+1);if(w>2048||h>2048)throw std::runtime_error("Diagnostic module too large");std::vector<u32> screen(usize(w)*h,0);require(bg->draw_module(m,{screen.data(),w,h,w,screen.size()}),name);ppm(output/(stem+"_"+mod.name+".ppm"),screen,w,h);++modulecount;}}}std::cout<<"PASS: "<<pack->count<<" source files, "<<images<<" images, "<<bgcount<<" BDD/BDB pairs, "<<modulecount<<" editor module captures.\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
